  /** Primary product image. */
  media?: string;
  /** Current selling price (amount, currency, formatted). */
  price?: Money;
  /** Compare-at price (original price before discount). Present only when the product is discounted. */
  compareAtPrice?: Money;
  /**
   * Optional badge text displayed on the product card (e.g., "Sale", "New").
   * @maxLength 100
   */
